-- Amlak 058 CRM schema
create table if not exists public.crm_customers (
 id bigint generated by default as identity primary key,
 full_name text not null check(length(btrim(full_name)) between 2 and 120),
 phone text not null check(length(btrim(phone)) between 8 and 20),
 customer_type text not null default 'buyer' check(customer_type in ('buyer','seller','landlord','tenant','investor','other')),
 transaction_type text check(transaction_type is null or transaction_type in ('buy','sell','rent','rent_out','short_rent')),
 property_type text, city text not null default 'بجنورد', neighborhoods text[] not null default '{}',
 budget_min numeric(16,2), budget_max numeric(16,2), area_min numeric(10,2), area_max numeric(10,2),
 source text not null default 'manual' check(source in ('manual','website','telegram','phone','referral','other')),
 status text not null default 'new' check(status in ('new','contacted','qualified','negotiating','converted','inactive')),
 notes text, next_follow_up_at timestamptz, assigned_to uuid references auth.users(id) on delete set null,
 created_by uuid references auth.users(id) on delete set null default auth.uid(),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(budget_min is null or budget_max is null or budget_min<=budget_max),
 check(area_min is null or area_max is null or area_min<=area_max)
);
create index if not exists crm_customers_phone_idx on public.crm_customers(phone);
create index if not exists crm_customers_status_idx on public.crm_customers(status);
create index if not exists crm_customers_followup_idx on public.crm_customers(next_follow_up_at) where next_follow_up_at is not null;
create table if not exists public.crm_activities (
 id bigint generated by default as identity primary key,
 customer_id bigint not null references public.crm_customers(id) on delete cascade,
 activity_type text not null default 'note' check(activity_type in ('call','meeting','message','note','follow_up')),
 description text not null check(length(btrim(description)) between 1 and 3000),
 scheduled_at timestamptz, completed_at timestamptz,
 created_by uuid references auth.users(id) on delete set null default auth.uid(), created_at timestamptz not null default now()
);
create index if not exists crm_activities_customer_idx on public.crm_activities(customer_id,created_at desc);
alter table public.crm_customers enable row level security;
alter table public.crm_activities enable row level security;
drop policy if exists crm_customers_admin_select on public.crm_customers;
create policy crm_customers_admin_select on public.crm_customers for select to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_customers_admin_insert on public.crm_customers;
create policy crm_customers_admin_insert on public.crm_customers for insert to authenticated with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_customers_admin_update on public.crm_customers;
create policy crm_customers_admin_update on public.crm_customers for update to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_customers_admin_delete on public.crm_customers;
create policy crm_customers_admin_delete on public.crm_customers for delete to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_activities_admin_select on public.crm_activities;
create policy crm_activities_admin_select on public.crm_activities for select to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_activities_admin_insert on public.crm_activities;
create policy crm_activities_admin_insert on public.crm_activities for insert to authenticated with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_activities_admin_update on public.crm_activities;
create policy crm_activities_admin_update on public.crm_activities for update to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
drop policy if exists crm_activities_admin_delete on public.crm_activities;
create policy crm_activities_admin_delete on public.crm_activities for delete to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
grant select,insert,update,delete on public.crm_customers,public.crm_activities to authenticated;
grant usage,select on all sequences in schema public to authenticated;